package com.demo.upimesh.model;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.time.Instant;

/**
 * Immutable domain record representing an offline spend instruction generated by an authorized device.
 * Cryptographically bound to the original bank authority voucher, payer device, recipient, sequence,
 * and cumulative spending evidence.
 */
public record OfflineSpendRecord(
        String allowanceId,
        String paymentId,
        String payerAccountId,
        String payerDeviceId,
        String recipientAccountId,
        BigDecimal amount,
        String currency,
        int sequenceNumber,
        BigDecimal cumulativeSpentAmount,
        Instant createdAt,
        String voucherSignature,
        String payerSignature,
        int protocolVersion
) {
    public static final String CANONICAL_HEADER = "UPI-MESH-SPEND-V1";
    public static final int CURRENT_PROTOCOL_VERSION = 1;

    public static String canonicalAmount(BigDecimal amount) {
        if (amount == null) return "0.00";
        if (amount.scale() <= 2) {
            return amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
        }
        return amount.stripTrailingZeros().toPlainString();
    }

    public byte[] toCanonicalSpendBytes() {
        return buildCanonicalSpendBytes(
                this.allowanceId,
                this.paymentId,
                this.payerAccountId,
                this.payerDeviceId,
                this.recipientAccountId,
                this.amount,
                this.currency,
                this.sequenceNumber,
                this.cumulativeSpentAmount,
                this.createdAt,
                this.voucherSignature,
                this.protocolVersion
        );
    }

    public static byte[] buildCanonicalSpendBytes(
            String allowanceId,
            String paymentId,
            String payerAccountId,
            String payerDeviceId,
            String recipientAccountId,
            BigDecimal amount,
            String currency,
            int sequenceNumber,
            BigDecimal cumulativeSpentAmount,
            Instant createdAt,
            String voucherSignature,
            int protocolVersion
    ) {
        String cleanAlw = allowanceId != null ? allowanceId.trim() : "";
        String cleanPayId = paymentId != null ? paymentId.trim() : "";
        String cleanPayer = payerAccountId != null ? payerAccountId.trim().toLowerCase() : "";
        String cleanDev = payerDeviceId != null ? payerDeviceId.trim() : "";
        String cleanRecip = recipientAccountId != null ? recipientAccountId.trim().toLowerCase() : "";
        String amtStr = canonicalAmount(amount);
        String cleanCurr = currency != null ? currency.trim().toUpperCase() : "INR";
        String seqStr = String.valueOf(sequenceNumber);
        String cumStr = canonicalAmount(cumulativeSpentAmount);
        String timeStr = createdAt != null ? createdAt.toString() : "";
        String cleanVoucherSig = voucherSignature != null ? voucherSignature.trim() : "";
        int version = protocolVersion > 0 ? protocolVersion : CURRENT_PROTOCOL_VERSION;

        StringBuilder sb = new StringBuilder();
        sb.append(CANONICAL_HEADER).append("\n");
        sb.append("allowanceId:").append(cleanAlw.length()).append(":").append(cleanAlw).append("\n");
        sb.append("paymentId:").append(cleanPayId.length()).append(":").append(cleanPayId).append("\n");
        sb.append("payerAccountId:").append(cleanPayer.length()).append(":").append(cleanPayer).append("\n");
        sb.append("payerDeviceId:").append(cleanDev.length()).append(":").append(cleanDev).append("\n");
        sb.append("recipientAccountId:").append(cleanRecip.length()).append(":").append(cleanRecip).append("\n");
        sb.append("currency:").append(cleanCurr.length()).append(":").append(cleanCurr).append("\n");
        sb.append("amount:").append(amtStr.length()).append(":").append(amtStr).append("\n");
        sb.append("sequenceNumber:").append(seqStr.length()).append(":").append(seqStr).append("\n");
        sb.append("cumulativeSpentAmount:").append(cumStr.length()).append(":").append(cumStr).append("\n");
        sb.append("createdAt:").append(timeStr.length()).append(":").append(timeStr).append("\n");
        sb.append("voucherSignature:").append(cleanVoucherSig.length()).append(":").append(cleanVoucherSig).append("\n");
        sb.append("version:").append(String.valueOf(version).length()).append(":").append(version).append("\n");

        return sb.toString().getBytes(StandardCharsets.UTF_8);
    }
}
